```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0xb93430ce38ac4a6bb47fb1fc085ea669353fd89e.sol";

contract TimestampManipulationTest is Test {
    PrivateBank privateBank;
    Log logContract;
    address user = vm.addr(1);

    function setUp() public {
        vm.deal(user, 100 ether);
        logContract = new Log();
        privateBank = new PrivateBank(address(logContract));
    }

    function test_timestampManipulation() public {
        vm.startPrank(user);
        uint256 amount1 = 1 ether;
        uint256 amount2 = 2 ether;
        uint256 timestamp1 = 1000;
        uint256 timestamp2 = 2000;

        // First deposit at timestamp1
        vm.warp(timestamp1);
        privateBank.Deposit{value: amount1}();

        // Second deposit at timestamp2
        vm.warp(timestamp2);
        privateBank.Deposit{value: amount2}();
        vm.stopPrank();

        // Check first deposit record
        (address sender0, string memory data0, uint256 u1_0, uint256 u2_0) = logContract.History(0);
        assertEq(sender0, user, "First deposit: sender mismatch");
        assertEq(data0, "Deposit", "First deposit: data mismatch");

        uint256 recordedT0;
        if (u1_0 == timestamp1) recordedT0 = u1_0;
        if (u2_0 == timestamp1) recordedT0 = u2_0;
        assertEq(recordedT0, timestamp1, "First deposit: timestamp not found");

        assertTrue(
            (u1_0 == amount1 && u2_0 != amount1) || 
            (u2_0 == amount1 && u1_0 != amount1),
            "First deposit: value not recorded"
        );

        // Check second deposit record
        (address sender1, string memory data1, uint256 u1_1, uint256 u2_1) = logContract.History(1);
        assertEq(sender1, user, "Second deposit: sender mismatch");
        assertEq(data1, "Deposit", "Second deposit: data mismatch");

        uint256 recordedT1;
        if (u1_1 == timestamp2) recordedT1 = u1_1;
        if (u2_1 == timestamp2) recordedT1 = u2_1;
        assertEq(recordedT1, timestamp2, "Second deposit: timestamp not found");

        assertTrue(
            (u1_1 == amount2 && u2_1 != amount2) || 
            (u2_1 == amount2 && u1_1 != amount2),
            "Second deposit: value not recorded"
        );
    }
}
```
