        uint256 amount1 = 1 ether;
        uint256 amount2 = 2 ether;
        uint256 timestamp1 = 1000;
        uint256 timestamp2 = 2000;

        console2.log("[PRE] User balance:", user.balance);

        // First deposit at timestamp1
        console2.log("--- BEFORE-Trigger (First Deposit) ---");
        uint256 preFirstDepositLogs = logContract.index();
        console2.log("Existing logs:", preFirstDepositLogs);

        console2.log("--- Trigger First Deposit ---");
        vm.warp(timestamp1);
        privateBank.Deposit{value: amount1}();

        console2.log("--- AFTER-Trigger (First Deposit) ---");
        (address sender0, string memory data0, uint256 u1_0, uint256 u2_0) = logContract.History(0);
        console2.log("Log[0] - sender: %s, data: '%s', u1: %s, u2: %s", sender0, data0, u1_0, u2_0);
        console2.log("Updated logs:", logContract.index());

        // Second deposit at timestamp2
        console2.log("--- BEFORE-Trigger (Second Deposit) ---");
        console2.log("User balance after first deposit:", user.balance);

        console2.log("--- Trigger Second Deposit ---");
        vm.warp(timestamp2);
        privateBank.Deposit{value: amount2}();
        vm.stopPrank();

        console2.log("--- AFTER-Trigger (Second Deposit) ---");
        (address sender1, string memory data1, uint256 u1_1, uint256 u2_1) = logContract.History(1);
        console2.log("Log[1] - sender: %s, data: '%s', u1: %s, u2: %s", sender1, data1, u1_1, u2_1);
        console2.log("Final logs count:", logContract.index());

        bool vulnerabilityConfirmed = true;
        string memory reason = "";

        // Validate first deposit record
        if (sender0 != user) {
            vulnerabilityConfirmed = false;
            reason = "First deposit sender mismatch";
        } else if (keccak256(abi.encodePacked(data0)) != keccak256(abi.encodePacked("Deposit"))) {
            vulnerabilityConfirmed = false;
            reason = "First deposit data mismatch";
        } else if (u1_0 != amount1) {
            vulnerabilityConfirmed = false;
            reason = "First deposit amount not recorded";
        } else if (u2_0 != timestamp1) {
            vulnerabilityConfirmed = false;
            reason = "First deposit timestamp not recorded";
        }

        // Validate second deposit record
        if (vulnerabilityConfirmed) {
            if (sender1 != user) {
                vulnerabilityConfirmed = false;
                reason = "Second deposit sender mismatch";
            } else if (keccak256(abi.encodePacked(data1)) != keccak256(abi.encodePacked("Deposit"))) {
                vulnerabilityConfirmed = false;
                reason = "Second deposit data mismatch";
            } else if (u1_1 != amount2) {
                vulnerabilityConfirmed = false;
                reason = "Second deposit amount not recorded";
            } else if (u2_1 != timestamp2) {
                vulnerabilityConfirmed = false;
                reason = "Second deposit timestamp not recorded";
            }
        }

        // Final verdict
        if (vulnerabilityConfirmed) {
            console2.log("Vulnerability Exists: Timestamps were successfully manipulated and recorded in logs");
        } else {
            console2.log("Vulnerability not Exist: %s", reason);
        }
    }
}
